import json, re, sys
p = '/home/rob/.openclaw/openclaw.json'
data = json.load(open(p))
def walk(node, path=''):
    if isinstance(node, dict):
        for k,v in node.items():
            walk(v, path + '.' + k)
    elif isinstance(node, list):
        for i,v in enumerate(node):
            walk(v, path + f'[{i}]')
    else:
        s = str(node)
        if re.search(r'(model|provider|primary|fallback|timeout)', path, re.I):
            print(path, '=', s[:120])
" 2>&1 | head -60

python3 << 'EOF'
import json
with open('/home/rob/.openclaw/openclaw.json') as f:
    try:
        cfg = json.load(f)
    except json.JSONDecodeError as e:
        print("JSON parse error:", e)
        raise SystemExit
agent = cfg.get('agent') or cfg.get('agents') or {}
def dump(k, v, depth=0):
    if isinstance(v, dict):
        for kk, vv in v.items():
            dump(f'{k}.{kk}', vv, depth+1)
    elif isinstance(v, list):
        for i, vv in enumerate(v):
            dump(f'{k}[{i}]', vv, depth+1)
    else:
        print(f'{k} = {v}')
for top in ('model', 'models', 'modelFallbacks', 'agent', 'provider', 'providers', 'llm'):
    if top in cfg:
        print(f'--- {top} ---')
        dump(top, cfg[top])
EOF

